/* ============================================================
   marketing-globe.js - the landing hero's spinning dot globe.
   (Owner 2026-10-12, HERO GLOBE directive.)

   Engine: hand-written Canvas 2D orthographic dot globe. No React,
   no three.js, no WebGL, no GPU-tier library, zero runtime
   dependencies. Land comes from a 1-bit mask generated from
   Natural Earth 110m data (public domain) by
   tools/gen-globe-mask.cjs - see that script for the source and
   licence. If the mask is empty the globe falls back to an even
   latitude/longitude dot grid rather than to nothing.

   Progressive enhancement, and this is the whole point of the
   design: the three existing hero cards stay in the HTML as the
   no-JS / reduced-motion / failure fallback. Nothing here removes
   them. This module only ADDS a stage on top, and the cards are
   hidden - by visibility, never display, so the column keeps its
   height and the page never shifts - once the canvas has drawn
   its first frame.

   Loaded ONLY by index.html's idle loader, after load, so the
   hero headline is the LCP and this never competes with it.
   ============================================================ */
(function () {
  'use strict';

  /* LAND-MASK-BEGIN (generated by tools/gen-globe-mask.cjs - do not edit) */
  var LAND_MASK_B64 =
    '';
  /* LAND-MASK-END */

  // Mask geometry - must match the generator (1 degree cells, south to north).
  var MASK_LAT_FROM = -85;
  var MASK_COLS = 360;
  var MASK_ROWS = 171;
  var MASK_LAT_STEP = 1;

  // Poster / canvas geometry. The generated poster is drawn with exactly
  // these numbers, so the cross-fade from poster to canvas is invisible.
  var LON0 = -30; // starting rotation, degrees
  var LAT0 = 17.97; // starting tilt - Jamaica's own latitude
  var DOT_STEP = 2; // degrees between dots
  var POSTER_W = 900;
  var POSTER_H = 760;

  // Cycle timing (owner directive section 3).
  var CYCLE = 10000;
  var CARD_IN = 1600; // card pops once the globe has eased to the node
  var CARD_OUT = 7200; // retract - leaves a long spin gap before the next pop
  var EASE_TAU = 300; // damping time constant, ms
  var SPIN = 3.5; // idle spin, degrees per second (<= 4 as specified)
  var RESUME_AFTER = 4000; // auto-cycle resumes this long after interaction
  var FRAME_BUDGET = 24; // ms - watchdog threshold
  var WATCH_FRAMES = 60;

  // ---------------------------------------------------------------
  // THE FEATURE MANIFEST (one constant, as the directive requires).
  // Every entry was verified against its source before it was kept,
  // and the ones that could not be verified were dropped - see the
  // "what was dropped" note at the bottom of this file.
  //   href   - an existing page or anchor (checked by qa-hero-globe G7)
  //   tier   - 'free' or 'premium'
  //   lat/lon - the node this feature pops out of
  //   art    - optional card art, reused from the existing hero SVGs
  // ---------------------------------------------------------------
  var FEATURES = [
    {
      id: 'schedule',
      title: 'Schedule and Gantt',
      blurb: 'Plan the work in a WBS, then watch it as a Gantt with float and critical chains.',
      href: 'features.html#f-wbs',
      tier: 'free',
      lat: 40.71,
      lon: -74.01,
      art: 'images/hero-schedule.svg'
    },
    {
      id: 'budget',
      title: 'Budget and EVM',
      blurb: 'Planned against earned, cost index and forecast, all fed by the same numbers.',
      href: 'features.html#f-budget',
      tier: 'free',
      lat: 51.51,
      lon: -0.13,
      art: 'images/hero-evm-chart.svg'
    },
    {
      id: 'ai',
      title: 'My MaNaGeR AI',
      blurb:
        'Ask about your live project in plain words and get an answer read from your own data.',
      href: 'features.html#f-ai',
      tier: 'free',
      lat: 37.39,
      lon: -122.08,
      art: 'images/hero-ai-roadmap.svg'
    },
    {
      id: 'calculator',
      title: 'Cost calculator with JIC rates',
      blurb: 'Price a build in minutes with the published JIC 2025-2027 rate book built in.',
      href: 'calculator.html',
      tier: 'free',
      lat: 17.97,
      lon: -76.79
    },
    {
      id: 'montecarlo',
      title: 'Monte Carlo schedule risk',
      blurb: 'Run the schedule thousands of times and see the dates you can actually promise.',
      href: 'features.html#f-risk',
      tier: 'free',
      lat: 46.82,
      lon: 8.23
    },
    {
      id: 'workspace',
      title: 'Project workspace',
      blurb: 'Eighteen panels that share one project, so one change updates every view.',
      // The features page IS the eighteen-panels tour; it carries no #features
      // anchor (that id only exists on index.html), so the card links to the
      // page itself rather than to an anchor that would not scroll.
      href: 'features.html',
      tier: 'free',
      lat: 35.69,
      lon: 139.69
    },
    {
      id: 'risks',
      title: 'Risks and issues',
      blurb: 'Log what could go wrong, score it, and keep the register where the work is.',
      href: 'mymanager-field-guide.html#risk',
      tier: 'free',
      lat: -33.92,
      lon: 18.42
    },
    {
      id: 'offline',
      title: 'Offline and voice',
      blurb: 'Keep working with no signal, and capture site notes by voice as you walk.',
      href: 'features.html#f-offline',
      tier: 'free',
      lat: 64.14,
      lon: -21.93
    },
    {
      id: 'mcp',
      title: 'MCP server',
      blurb:
        'Point an AI tool at a project over MCP. Optional - the app works the same without it.',
      href: 'mymanager-field-guide.html#connect-ai',
      tier: 'premium',
      lat: 47.61,
      lon: -122.33
    }
  ];

  var HOME = { lat: 17.97, lon: -76.79 }; // Kingston, Jamaica - the gold pin

  // ---------------------------------------------------------------
  // Small helpers
  // ---------------------------------------------------------------
  var TAU = Math.PI * 2;
  var rad = function (d) {
    return (d * Math.PI) / 180;
  };
  var clamp = function (v, a, b) {
    return v < a ? a : v > b ? b : v;
  };
  // Shortest-arc difference between two longitudes, in degrees.
  var lonDelta = function (to, from) {
    var d = (to - from) % 360;
    if (d > 180) {
      d -= 360;
    }
    if (d < -180) {
      d += 360;
    }
    return d;
  };

  var _rawNow =
    typeof performance !== 'undefined' && performance && typeof performance.now === 'function'
      ? function () {
          return performance.now();
        }
      : function () {
          return Date.now();
        };
  // The clock the cycle reads. QA drives it through __advance, which moves
  // this offset forward instead of waiting in real time.
  var _clockOffset = 0;
  function now() {
    return _rawNow() + _clockOffset;
  }

  // ---------------------------------------------------------------
  // The land mask
  // ---------------------------------------------------------------
  var _mask = null;
  function mask() {
    if (_mask) {
      return _mask;
    }
    if (!LAND_MASK_B64 || typeof atob !== 'function') {
      _mask = new Uint8Array(0);
      return _mask;
    }
    try {
      var bin = atob(LAND_MASK_B64);
      var bytes = new Uint8Array(bin.length);
      for (var i = 0; i < bin.length; i++) {
        bytes[i] = bin.charCodeAt(i);
      }
      _mask = bytes;
    } catch (e) {
      _mask = new Uint8Array(0);
    }
    return _mask;
  }
  function isLand(lat, lon) {
    var m = mask();
    if (!m.length) {
      return true;
    } // FALLBACK (directive section 2): even dot grid
    var row = Math.round((lat - MASK_LAT_FROM) / MASK_LAT_STEP);
    var col = Math.round(lon + 180);
    if (row < 0 || row >= MASK_ROWS || col < 0 || col >= MASK_COLS) {
      return false;
    }
    var i = row * MASK_COLS + col;
    return !!(m[i >> 3] & (1 << (7 - (col & 7))));
  }

  // Precomputed dot table: for every land cell on the dot grid, the four
  // trig values the projection needs, so a frame costs a handful of multiplies
  // per dot instead of four transcendentals.
  var _dots = null;
  function dots() {
    if (_dots) {
      return _dots;
    }
    var lats = [],
      lons = [],
      sL = [],
      cL = [],
      sM = [],
      cM = [];
    for (var lat = -85; lat <= 85; lat += DOT_STEP) {
      for (var lon = -180; lon < 180 - DOT_STEP / 2; lon += DOT_STEP) {
        if (!isLand(lat, lon)) {
          continue;
        }
        lats.push(lat);
        lons.push(lon);
        sL.push(Math.sin(rad(lat)));
        cL.push(Math.cos(rad(lat)));
        sM.push(Math.sin(rad(lon)));
        cM.push(Math.cos(rad(lon)));
      }
    }
    _dots = {
      n: lats.length,
      lat: Float32Array.from(lats),
      lon: Float32Array.from(lons),
      sLat: Float32Array.from(sL),
      cLat: Float32Array.from(cL),
      sLon: Float32Array.from(sM),
      cLon: Float32Array.from(cM)
    };
    return _dots;
  }

  // ---------------------------------------------------------------
  // State
  // ---------------------------------------------------------------
  var stage = null,
    frame = null,
    canvas = null,
    ctx = null,
    tether = null,
    tetherLine = null,
    cardsBox = null,
    controls = null,
    cardEls = [],
    tabEls = [];

  var state = {
    index: 0,
    next: 0, // the next RANDOM feature to ease toward during the spin gap
    wraps: 0, // monotonic cycle counter - QA asserts the cycle KEEPS RUNNING
    t: 0,
    lon: LON0,
    lat: LAT0,
    paused: false, // the user pressed Pause - it STAYS paused
    interacting: false, // hover or focus-within
    resumeAt: 0,
    dragging: false,
    hidden: false,
    offscreen: false,
    quality: 0, // 0 = full dot count, 1 = halved
    frozen: false,
    started: false,
    firstFrame: false
  };

  var _raf = 0,
    _last = 0,
    _obs = null,
    _samples = [],
    _listeners = [],
    _resize = null,
    _cardTimer = 0,
    _open = -1;

  function running() {
    return (
      state.started &&
      !state.paused &&
      !state.hidden &&
      !state.offscreen &&
      !state.dragging &&
      !state.frozen &&
      (!state.interacting || now() >= state.resumeAt)
    );
  }

  // ---------------------------------------------------------------
  // Projection + rendering
  // ---------------------------------------------------------------
  var _cw = 0,
    _ch = 0,
    _R = 0,
    _cx = 0,
    _cy = 0,
    _shift = 0,
    _shiftTarget = 0;

  function measure() {
    if (!frame || !canvas) {
      return;
    }
    var box = frame.getBoundingClientRect();
    if (!box.width || !box.height) {
      return;
    }
    _cw = box.width;
    _ch = box.height;
    var dpr = Math.min(2, window.devicePixelRatio || 1); // cap at 2, per directive
    canvas.width = Math.round(_cw * dpr);
    canvas.height = Math.round(_ch * dpr);
    canvas.style.width = _cw + 'px';
    canvas.style.height = _ch + 'px';
    ctx = canvas.getContext('2d');
    if (ctx) {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    }
    _R = (_ch * 300) / POSTER_H; // same radius the poster used
    _cx = _cw / 2;
    _cy = _ch / 2;
  }

  // Orthographic: given a lat/lon and the current rotation, where does it land
  // and is it on the near side. Pure function of the rotation, so the node the
  // card opens on is exactly the dot the pin is drawn on.
  function project(lat, lon) {
    var p0 = rad(state.lat),
      l0 = rad(state.lon);
    var sp0 = Math.sin(p0),
      cp0 = Math.cos(p0);
    var phi = rad(lat),
      sP = Math.sin(phi),
      cP = Math.cos(phi),
      lam = rad(lon);
    var sLam = Math.sin(lam),
      cLam = Math.cos(lam);
    var cosD = cLam * Math.cos(l0) + sLam * Math.sin(l0);
    var sinD = sLam * Math.cos(l0) - cLam * Math.sin(l0);
    var z = sp0 * sP + cp0 * cP * cosD;
    return {
      x: _cx + _shift + cP * sinD * _R,
      y: _cy - (cp0 * sP - sp0 * cP * cosD) * _R,
      z: z
    };
  }

  var BUCKETS = 6;

  function render() {
    if (!ctx || !_cw) {
      return;
    }
    var d = dots();
    ctx.clearRect(0, 0, _cw, _ch);
    if (!d.n) {
      return;
    }

    // Rim glow, drawn first so the dots sit on it.
    var g = ctx.createRadialGradient(_cx + _shift, _cy, _R * 0.72, _cx + _shift, _cy, _R + 26);
    g.addColorStop(0, 'rgba(217,107,39,0)');
    g.addColorStop(0.92, 'rgba(217,107,39,0.30)');
    g.addColorStop(1, 'rgba(217,107,39,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(_cx + _shift, _cy, _R + 26, 0, TAU);
    ctx.fill();

    var sp0 = Math.sin(rad(state.lat)),
      cp0 = Math.cos(rad(state.lat));
    var l0 = rad(state.lon),
      c0 = Math.cos(l0),
      s0 = Math.sin(l0);
    var n = d.n;
    var skip = state.quality === 1 ? 2 : 1; // watchdog halves the dot count
    var rad2 = 0.9 + (_R / 300) * 1.5;

    // Bucket by depth so the whole globe costs BUCKETS fills, not n of them.
    var bx = [],
      by = [],
      bc = [];
    for (var b = 0; b < BUCKETS; b++) {
      bx.push(new Float32Array(n));
      by.push(new Float32Array(n));
      bc.push(0);
    }
    for (var i = 0; i < n; i += skip) {
      var cLat = d.cLat[i],
        sLat = d.sLat[i],
        cLon = d.cLon[i],
        sLon = d.sLon[i];
      var cosD = cLon * c0 + sLon * s0;
      var sinD = sLon * c0 - cLon * s0;
      var z = sp0 * sLat + cp0 * cLat * cosD;
      if (z <= 0.015) {
        continue;
      }
      var k = Math.min(BUCKETS - 1, Math.floor(z * BUCKETS));
      var x = _cx + _shift + cLat * sinD * _R;
      var y = _cy - (cp0 * sLat - sp0 * cLat * cosD) * _R;
      bx[k][bc[k]] = x;
      by[k][bc[k]] = y;
      bc[k]++;
    }
    ctx.fillStyle = '#ffe082'; // --accent-on-navy, the marketing gold
    for (var k2 = 0; k2 < BUCKETS; k2++) {
      var c2 = bc[k2];
      if (!c2) {
        continue;
      }
      ctx.globalAlpha = ((k2 + 0.6) / BUCKETS) * 0.92;
      ctx.beginPath();
      for (var j = 0; j < c2; j++) {
        var xx = bx[k2][j],
          yy = by[k2][j];
        ctx.moveTo(xx + rad2, yy);
        ctx.arc(xx, yy, rad2, 0, TAU);
      }
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // The home pin: Kingston, Jamaica, with a soft pulse.
    var home = project(HOME.lat, HOME.lon);
    if (home.z > 0) {
      var pulse = (now() % 2400) / 2400;
      ctx.strokeStyle = '#d96b27';
      ctx.globalAlpha = 0.34 * (1 - pulse);
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(home.x, home.y, 5 + pulse * 9, 0, TAU);
      ctx.stroke();
      ctx.globalAlpha = 1;
      ctx.fillStyle = '#ffe082';
      ctx.beginPath();
      ctx.arc(home.x, home.y, 3.2, 0, TAU);
      ctx.fill();
    }
  }

  // ---------------------------------------------------------------
  // Cycle
  // ---------------------------------------------------------------
  function target() {
    var f = FEATURES[state.index];
    if (state.t >= CARD_OUT) {
      f = FEATURES[state.next]; // ease to the NEXT (random) node
    }
    return f;
  }

  // A random feature index that is NOT `exclude`, so consecutive pops never
  // repeat the same node.
  function pickOther(exclude) {
    if (FEATURES.length < 2) {
      return exclude;
    }
    var i = exclude;
    while (i === exclude) {
      i = Math.floor(Math.random() * FEATURES.length); // ok: non-secret
    }
    return i;
  }

  function step(dt) {
    if (!running()) {
      return;
    }
    state.t += dt;
    if (state.t >= CYCLE) {
      state.t -= CYCLE;
      state.wraps++;
      state.index = state.next;
      state.next = pickOther(state.index);
      setCard(state.index, false);
    }
    var f = target();
    // LAND-2 (REFINEMENT-DIRECTIVE-2026-10-24): the globe turns CONTINUOUSLY.
    // It used to stop dead while a card was showing, which read as a frozen
    // globe. Now the spin never stops; a card follows its node through the
    // rotation (positionCard reads the live projection every frame).
    var spinStep = (SPIN * dt) / 1000;
    var lonBefore = state.lon;
    state.lon += spinStep;
    var k = 1 - Math.exp(-dt / EASE_TAU); // time-based damping, frame-rate safe
    // While a card is open the view must NOT ease back toward the node - that
    // is what used to cancel the spin. The card simply travels with it.
    if (_open === -1) {
      state.lon += lonDelta(f.lon, state.lon) * k;
    }
    // The ease exists to bring a node to the front; it must never be able to
    // cancel the rotation and leave the globe looking stuck. The check is on
    // the SIGNED turn: if a frame ends up turning less than 60 percent of its
    // spin forward (including turning backwards to reach a node behind us),
    // the frame simply keeps the spin and the node is approached over more
    // frames instead.
    if (lonDelta(state.lon, lonBefore) < spinStep * 0.6) {
      state.lon = lonBefore + spinStep;
    }
    state.lat += (clamp(f.lat, -55, 60) - state.lat) * k;
    if (state.lon > 180) {
      state.lon -= 360;
    }
    if (state.lon < -180) {
      state.lon += 360;
    }

    // Card in / out.
    if (state.t >= CARD_IN && state.t < CARD_OUT && _open !== state.index) {
      setCard(state.index, true);
    } else if (state.t >= CARD_OUT && _open !== -1) {
      setCard(state.index, false);
    }
    // A card whose node has turned away from the reader is closed early rather
    // than left tethered to the back of the globe. Once the node is more than
    // 70 degrees from the view centre, or has gone behind it, the card retracts
    // and the normal gap runs before the next node pops.
    if (_open !== -1) {
      var away = Math.abs(lonDelta(FEATURES[_open].lon, state.lon));
      var nodeP = project(FEATURES[_open].lat, FEATURES[_open].lon);
      if (away > 70 || nodeP.z <= 0) {
        setCard(_open, false);
        if (state.t < CARD_OUT) {
          state.t = CARD_OUT;
        }
      }
    }

    _shiftTarget = _open === -1 ? 0 : cardSide() === 'right' ? -0.1 * _cw : 0.1 * _cw;
    _shift += (_shiftTarget - _shift) * k;
  }

  function cardSide() {
    var f = FEATURES[state.index];
    var p = project(f.lat, f.lon);
    return p.x >= _cx + _shift ? 'right' : 'left';
  }

  function positionCard() {
    var el = cardEls[_open];
    if (!el || !tetherLine || !_cw) {
      return;
    }
    var f = FEATURES[_open];
    var p = project(f.lat, f.lon);
    var side = cardSide();
    var w = el.offsetWidth,
      h = el.offsetHeight;
    var anchorX = side === 'right' ? _cw - w : w;
    var top = clamp(p.y, h / 2 + 10, _ch - h / 2 - 10);
    // Only TOP is set here: the pop and the centring transform belong to CSS,
    // so an inline transform could never fight the scale/opacity animation.
    el.style.top = top + 'px';
    if (side === 'right') {
      el.style.left = 'auto';
      el.style.right = '0px';
    } else {
      el.style.right = 'auto';
      el.style.left = '0px';
    }
    // Tether: node -> the card edge that faces the globe.
    tetherLine.setAttribute('x1', p.x.toFixed(1));
    tetherLine.setAttribute('y1', p.y.toFixed(1));
    tetherLine.setAttribute('x2', anchorX.toFixed(1));
    tetherLine.setAttribute('y2', top.toFixed(1));
    tetherLine.style.opacity = p.z > 0 ? '1' : '0';
  }

  function setCard(index, open) {
    if (_cardTimer) {
      clearTimeout(_cardTimer);
      _cardTimer = 0;
    }
    cardEls.forEach(function (el, i) {
      if (i !== index) {
        el.hidden = true;
        el.classList.remove('hg-open');
      }
    });
    if (!open) {
      if (_open !== -1 && cardEls[_open]) {
        var prev = cardEls[_open];
        prev.classList.remove('hg-open');
        _cardTimer = setTimeout(function () {
          prev.hidden = true;
        }, 320);
      }
      _open = -1;
      if (tabEls.length) {
        tabEls.forEach(function (t) {
          t.setAttribute('aria-current', 'false');
        });
      }
      return;
    }
    var el2 = cardEls[index];
    if (!el2) {
      return;
    }
    el2.hidden = false;
    // Force a frame so the pop transition actually runs from scale/opacity 0.
    void el2.offsetWidth;
    el2.classList.add('hg-open');
    _open = index;
    tabEls.forEach(function (t, i) {
      t.setAttribute('aria-current', i === index ? 'true' : 'false');
    });
    positionCard();
  }

  // ---------------------------------------------------------------
  // Frame loop + watchdog
  // ---------------------------------------------------------------
  function loop(ts) {
    _raf = requestAnimationFrame(loop);
    if (!_last) {
      _last = ts;
    }
    var dt = Math.min(100, ts - _last);
    _last = ts;
    step(dt);
    render();
    if (_open !== -1) {
      positionCard();
    }
    watchdog(dt);
    if (!state.firstFrame) {
      state.firstFrame = true;
      stage.classList.add('hg-first'); // poster cross-fades to the live canvas
      // Only NOW do the old cards go away - the globe has proved it renders.
      var visual = stage.closest('.hero-visual');
      if (visual) {
        visual.classList.add('hg-live');
      }
    }
  }

  function watchdog(dt) {
    _samples.push(dt);
    if (_samples.length < WATCH_FRAMES) {
      return;
    }
    var sum = 0;
    for (var i = 0; i < _samples.length; i++) {
      sum += _samples[i];
    }
    var avg = sum / _samples.length;
    _samples.length = 0;
    if (avg > FRAME_BUDGET) {
      if (state.quality === 0) {
        state.quality = 1; // halve the dots
      } else {
        state.frozen = true; // still too slow: freeze on one static frame
      }
    }
  }

  function start() {
    if (state.started || !stage) {
      return;
    }
    state.started = true;
    // The stage is display:none until this class lands, so it has to come
    // FIRST - measure() reads the frame's real box.
    stage.classList.add('hg-on');
    state.lon = LON0;
    state.lat = LAT0;
    state.index = 0;
    state.next = pickOther(0);
    measure();
    render();
    _last = 0;
    _raf = requestAnimationFrame(loop);
  }

  function stopLoop() {
    if (_raf) {
      cancelAnimationFrame(_raf);
    }
    _raf = 0;
    _last = 0;
  }

  // ---------------------------------------------------------------
  // DOM: controls, tabs, cards
  // ---------------------------------------------------------------
  function svgIcon(id) {
    var s = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    s.setAttribute('class', 'ico');
    s.setAttribute('aria-hidden', 'true');
    var u = document.createElementNS('http://www.w3.org/2000/svg', 'use');
    u.setAttribute('href', 'css/mmgr-icons.svg#' + id);
    s.appendChild(u);
    return s;
  }

  function build() {
    stage = document.getElementById('hero-globe');
    if (!stage) {
      return false;
    }
    frame = stage.querySelector('.hg-frame');
    canvas = stage.querySelector('.hg-canvas');
    tether = stage.querySelector('.hg-tether');
    cardsBox = stage.querySelector('.hg-cards');
    controls = stage.querySelector('.hg-controls');
    if (!frame || !canvas || !cardsBox || !controls) {
      return false;
    }
    if (!canvas.getContext || !canvas.getContext('2d')) {
      return false;
    }
    if (tether) {
      tether.setAttribute('viewBox', '0 0 ' + POSTER_W + ' ' + POSTER_H);
      tetherLine = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      tetherLine.setAttribute('class', 'hg-tether-line');
      tether.appendChild(tetherLine);
    }

    // Every feature is a real link, in the DOM from the moment the globe
    // starts - only the active one is visible.
    FEATURES.forEach(function (f) {
      var a = document.createElement('a');
      a.className = 'hg-card';
      a.href = f.href;
      a.hidden = true;
      var head = document.createElement('span');
      head.className = 'hg-card-head';
      var t = document.createElement('b');
      t.textContent = f.title;
      head.appendChild(t);
      if (f.tier === 'premium') {
        var badge = document.createElement('span');
        badge.className = 'hg-badge';
        badge.textContent = 'Premium';
        head.appendChild(badge);
      }
      a.appendChild(head);
      var blurb = document.createElement('span');
      blurb.className = 'hg-card-blurb';
      blurb.textContent = f.blurb;
      a.appendChild(blurb);
      if (f.art) {
        var img = document.createElement('img');
        img.src = f.art;
        img.alt = '';
        img.loading = 'lazy';
        img.width = 900;
        img.height = 491;
        img.setAttribute('draggable', 'false');
        a.appendChild(img);
      }
      var foot = document.createElement('span');
      foot.className = 'hg-card-foot';
      foot.appendChild(document.createTextNode(f.tier === 'premium' ? 'Premium plan' : 'Included'));
      foot.appendChild(svgIcon('i-arrow-right'));
      a.appendChild(foot);
      cardsBox.appendChild(a);
      cardEls.push(a);
    });

    wireHost();
    return true;
  }

  function bump() {
    state.resumeAt = now() + RESUME_AFTER; // 4 s, then the cycle carries on
  }
  function wireHost() {
    // Hover and focus-within pause the cycle; it resumes 4 s later unless the
    // user pressed Pause.
    var enter = function () {
      state.interacting = true;
      bump();
    };
    var leave = function () {
      state.interacting = false;
      bump();
    };
    stage.addEventListener('pointerenter', enter);
    stage.addEventListener('pointerleave', leave);
    stage.addEventListener('focusin', enter);
    stage.addEventListener('focusout', leave);
    _listeners.push(['pointerenter', stage, enter]);
    _listeners.push(['pointerleave', stage, leave]);
    _listeners.push(['focusin', stage, enter]);
    _listeners.push(['focusout', stage, leave]);

    var onVis = function () {
      var wasHidden = state.hidden;
      state.hidden = document.visibilityState === 'hidden';
      if (state.hidden) {
        stopLoop();
      } else if (!wasHidden && state.started && !state.frozen && !_raf) {
        _last = 0;
        _raf = requestAnimationFrame(loop);
      }
    };
    document.addEventListener('visibilitychange', onVis);
    _listeners.push(['visibilitychange', document, onVis]);

    if (typeof IntersectionObserver === 'function') {
      _obs = new IntersectionObserver(
        function (entries) {
          var vis = entries.some(function (en) {
            return en.isIntersecting;
          });
          state.offscreen = !vis;
          if (state.offscreen) {
            stopLoop();
          } else if (state.started && !state.frozen && !_raf) {
            _last = 0;
            _raf = requestAnimationFrame(loop);
          }
        },
        { threshold: 0.05 }
      );
      _obs.observe(stage);
    }

    _resize = function () {
      measure();
      render();
      if (_open !== -1) {
        positionCard();
      }
    };
    window.addEventListener('resize', _resize);
    _listeners.push(['resize', window, _resize]);
    window.addEventListener('pagehide', teardown);
    _listeners.push(['pagehide', window, teardown]);
  }

  // ---------------------------------------------------------------
  // Teardown - every listener, timer and observer this module made.
  // ---------------------------------------------------------------
  function teardown() {
    stopLoop();
    if (_cardTimer) {
      clearTimeout(_cardTimer);
      _cardTimer = 0;
    }
    _listeners.forEach(function (l) {
      l[1].removeEventListener(l[0], l[2]);
    });
    _listeners.length = 0;
    if (_obs) {
      _obs.disconnect();
      _obs = null;
    }
    state.started = false;
  }

  // ---------------------------------------------------------------
  // Entry - refuse to start when the directive says to stay still.
  // ---------------------------------------------------------------
  function shouldStart() {
    try {
      // PERF-1 (REFINEMENT-DIRECTIVE-2026-10-24): Performance Mode turns the
      // globe still. The poster in the markup is the static first frame, so the
      // hero keeps its artwork - only the animation stops. Checked through the
      // boot attribute as well as MMGR.Perf, because marketing pages set the
      // attribute from storage before this module loads.
      var perfAttr =
        document.documentElement && document.documentElement.getAttribute('data-perf') === 'on';
      var P = window.MMGR && window.MMGR.Perf;
      if (perfAttr || (P && P.blocksHeavyLayers && P.blocksHeavyLayers())) {
        return 'perf-mode';
      }
      if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        return 'reduced-motion';
      }
      var c = navigator.connection || navigator.webkitConnection;
      if (c && c.saveData) {
        return 'save-data';
      }
      if (!canvasSupport()) {
        return 'no-canvas';
      }
    } catch (e) {
      return 'error';
    }
    return '';
  }
  function canvasSupport() {
    try {
      var t = document.createElement('canvas');
      return !!(t.getContext && t.getContext('2d'));
    } catch (e) {
      return false;
    }
  }

  function boot() {
    var reason;
    try {
      if (!build()) {
        return;
      }
      reason = shouldStart();
      if (reason) {
        state.refuseReason = reason;
        return; // the existing cards stay exactly as they are
      }
      start();
    } catch (e) {
      // Any initialisation error leaves the cards and the static layout alone.
      state.refuseReason = 'error';
      state.started = false;
      try {
        stopLoop();
        if (stage) {
          stage.classList.remove('hg-on');
        }
      } catch (e2) {}
    }
  }

  // The QA seam (tools/qa-hero-globe.cjs). It only steps the same functions
  // the animation loop steps, so a gate can drive 40 s of cycle in
  // milliseconds without the test depending on wall-clock luck.
  function __advance(ms) {
    var left = ms;
    while (left > 0) {
      var dt = Math.min(16, left);
      left -= dt;
      _clockOffset += dt;
      step(dt);
    }
    render();
    if (_open !== -1) {
      positionCard();
    }
    return { index: state.index, t: state.t, open: _open };
  }

  window.MMGR_GLOBE = {
    features: FEATURES,
    state: state,
    start: start,
    teardown: teardown,
    render: render,
    project: function (lat, lon) {
      return project(lat, lon);
    },
    cardIndex: function () {
      return _open;
    },
    __advance: __advance,
    boot: boot
  };

  // PERF-1 (REFINEMENT-DIRECTIVE-2026-10-24): the switch can be flipped while
  // this page is open (the footer control writes the key and fires the event).
  // Turning Performance Mode ON stops the loop at once and leaves the poster as
  // the static first frame; turning it OFF starts the globe without a reload.
  document.addEventListener('mmgr:perf', function (e) {
    var on = !!(e && e.detail && e.detail.on);
    if (!stage) {
      return;
    }
    if (on) {
      stopLoop();
      return;
    }
    if (!state.started) {
      state.refuseReason = '';
      start();
      return;
    }
    if (!_raf && !state.hidden && !state.frozen) {
      _last = 0;
      _raf = requestAnimationFrame(loop);
    }
  });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot, { once: true });
  } else {
    boot();
  }
})();
